SELECT lower(hex(span_id)) AS span FROM tqd_cat.spans AS s WHERE start_ns >= 1790000000000000000 AND start_ns < 1790000060000000000 AND intDiv(start_ns, 300000000000) BETWEEN 5966666 AND 5966666 AND ((multiIf(dynamicType(attrs.`http%2Estatus_code`) != 'None', (coalesce(attrs.`http%2Estatus_code`.:Int64 = 200, false) OR coalesce(attrs.`http%2Estatus_code`.:Float64 = 200, false)), multiIf(has((SELECT groupArray(resource_id) FROM tqd_cat.resources WHERE dynamicType(attrs.`http%2Estatus_code`) != 'None'), resource_id), has((SELECT groupArray(resource_id) FROM tqd_cat.resources WHERE (coalesce(attrs.`http%2Estatus_code`.:Int64 = 200, false) OR coalesce(attrs.`http%2Estatus_code`.:Float64 = 200, false))), resource_id), multiIf(arrayExists(x -> dynamicType(x) != 'None', events.attrs.`http%2Estatus_code`), arrayExists(x -> x = 200, events.attrs.`http%2Estatus_code`.:Int64), multiIf(arrayExists(x -> dynamicType(x) != 'None', links.attrs.`http%2Estatus_code`), arrayExists(x -> x = 200, links.attrs.`http%2Estatus_code`.:Int64), multiIf(dynamicType(scope_attrs.`http%2Estatus_code`) != 'None', (coalesce(scope_attrs.`http%2Estatus_code`.:Int64 = 200, false) OR coalesce(scope_attrs.`http%2Estatus_code`.:Float64 = 200, false)), false))))))) ORDER BY span FORMAT TSV
SETTINGS final = 1, json_type_escape_dots_in_keys = 1, max_recursive_cte_evaluation_depth = 10001
